"""Latest evaluation results, produced by evals/run_evals.py (locally or in GitHub Actions)."""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd
import streamlit as st

st.set_page_config(page_title="Evals · AI Governance Assistant", page_icon="📊", layout="wide")
st.title("📊 Evals")
st.caption("How accurate is the assistant? Measured on a hand-checked golden set of 35 questions "
           "with reference answers, plus 14 adversarial prompts (off-topic, prompt injection, PII). "
           "Results are regenerated by GitHub Actions on every push (offline) and on demand (end-to-end).")

RESULTS = Path(__file__).resolve().parents[1] / "evals" / "results"


def show_md(name: str, title: str) -> dict | None:
    md, js = RESULTS / f"{name}.md", RESULTS / f"{name}.json"
    if not md.exists():
        st.info(f"No {title.lower()} results yet. See the README for how to run them.")
        return None
    data = json.loads(js.read_text()) if js.exists() else {}
    st.caption(f"Run at {data.get('timestamp', '?')}" + (f" · commit `{data['commit']}`" if data.get("commit") else ""))
    st.markdown(md.read_text().replace("## ", "#### ", 1))
    return data


tab1, tab2, tab3 = st.tabs(["End-to-end (LLM judge)", "Retrieval & guardrails", "Golden set"])
with tab1:
    full = show_md("full", "End-to-end")
    if full and full.get("rows"):
        df = pd.DataFrame(full["rows"])
        only_fail = st.toggle("Show failures only")
        if only_fail:
            df = df[~df["passed"]]
        cols = [c for c in ["id", "type", "status", "passed", "correctness", "faithfulness",
                            "reason", "latency_ms", "answer"] if c in df.columns]
        st.dataframe(df[cols], hide_index=True, width="stretch")
with tab2:
    show_md("offline", "Offline")
    cal = RESULTS / "calibrate.md"
    if cal.exists():
        st.markdown(cal.read_text().replace("## ", "#### ", 1))
with tab3:
    golden = [json.loads(l) for l in (RESULTS.parent / "golden.jsonl").read_text().splitlines() if l.strip()]
    st.dataframe(pd.DataFrame(golden), hide_index=True, width="stretch")
